#!/usr/bin/env python3
"""Merge user data from JSON, CSV and Parquet sources."""

import json
from pathlib import Path

import pandas as pd

SOURCE_A = "/data/source_a/users.json"
SOURCE_B = "/data/source_b/users.csv"
SOURCE_C = "/data/source_c/users.parquet"
OUTPUT_PARQUET = "/app/merged_users.parquet"
OUTPUT_CONFLICTS = "/app/conflicts.json"

PRIORITY = ["source_a", "source_b", "source_c"]

FIELD_ALIASES = {
    "user_id": ["user_id", "id", "userId"],
    "name": ["full_name", "name", "userName"],
    "email": ["email", "email_address"],
    "created_date": ["registration_date", "created_at", "joined"],
    "status": ["status", "is_active", "active"],
}

MERGE_FIELDS = ["name", "email", "created_date", "status"]
OUTPUT_COLUMNS = ["user_id", "name", "email", "created_date", "status"]


def is_missing(value):
    if value is None:
        return True
    try:
        return bool(pd.isna(value))
    except (TypeError, ValueError):
        return False


def clean_string(value):
    if is_missing(value):
        return None
    text = str(value).strip()
    return text if text else None


def normalize_user_id(value):
    if is_missing(value):
        return None
    if isinstance(value, str):
        value = value.strip()
        if not value:
            return None
    return int(float(value))


def normalize_date(value):
    if is_missing(value):
        return None
    parsed = pd.to_datetime(value, errors="coerce")
    if pd.isna(parsed):
        text = clean_string(value)
        return text
    return parsed.strftime("%Y-%m-%d")


def normalize_status(value):
    if is_missing(value):
        return None
    if isinstance(value, bool):
        return "active" if value else "inactive"
    text = clean_string(value)
    if text is None:
        return None
    lowered = text.lower()
    if lowered in {"true", "1", "yes", "active", "enabled"}:
        return "active"
    if lowered in {"false", "0", "no", "inactive", "disabled"}:
        return "inactive"
    return text


NORMALIZERS = {
    "user_id": normalize_user_id,
    "name": clean_string,
    "email": clean_string,
    "created_date": normalize_date,
    "status": normalize_status,
}


def load_source(source_name, path):
    if source_name == "source_a":
        with open(path, "r", encoding="utf-8") as handle:
            frame = pd.DataFrame(json.load(handle))
    elif source_name == "source_b":
        frame = pd.read_csv(path)
    else:
        frame = pd.read_parquet(path)

    renamed = {}
    for canonical, aliases in FIELD_ALIASES.items():
        for alias in aliases:
            if alias in frame.columns:
                renamed[alias] = canonical
                break
    frame = frame.rename(columns=renamed)

    records = []
    for _, row in frame.iterrows():
        record = {}
        for field, normalizer in NORMALIZERS.items():
            if field in frame.columns:
                record[field] = normalizer(row[field])
            else:
                record[field] = None
        user_id = record["user_id"]
        if user_id is None:
            continue
        records.append(record)
    return records


def main():
    sources = {
        "source_a": load_source("source_a", SOURCE_A),
        "source_b": load_source("source_b", SOURCE_B),
        "source_c": load_source("source_c", SOURCE_C),
    }

    by_user = {}
    for source_name in PRIORITY:
        for record in sources[source_name]:
            by_user.setdefault(record["user_id"], {})[source_name] = record

    merged_rows = []
    conflicts = []

    for user_id in sorted(by_user):
        per_source = by_user[user_id]
        merged = {"user_id": user_id}

        for field in MERGE_FIELDS:
            present = {
                source_name: per_source[source_name][field]
                for source_name in PRIORITY
                if source_name in per_source
                and per_source[source_name].get(field) is not None
            }

            selected = None
            for source_name in PRIORITY:
                if source_name in present:
                    selected = present[source_name]
                    break
            merged[field] = selected

            distinct = {str(value) for value in present.values()}
            if len(distinct) > 1:
                conflicts.append(
                    {
                        "user_id": user_id,
                        "field": field,
                        "values": present,
                        "selected": selected,
                    }
                )

        merged_rows.append(merged)

    output = pd.DataFrame(merged_rows, columns=OUTPUT_COLUMNS)
    output["user_id"] = output["user_id"].astype("int64")
    for column in ["name", "email", "created_date", "status"]:
        output[column] = output[column].astype("object")

    Path("/app").mkdir(parents=True, exist_ok=True)
    output.to_parquet(OUTPUT_PARQUET, index=False, engine="pyarrow")

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open(OUTPUT_CONFLICTS, "w", encoding="utf-8") as handle:
        json.dump(report, handle, indent=2, ensure_ascii=False)
        handle.write("\n")

    print(f"Wrote {len(output)} users to {OUTPUT_PARQUET}")
    print(f"Wrote {len(conflicts)} conflicts to {OUTPUT_CONFLICTS}")


if __name__ == "__main__":
    main()
PYEOF
